void epic_crc32_init(void) {
    if (crc32_ready) {
        return;
    }

    const uint32_t poly = 0xedb88320u;
    for (uint32_t i = 0; i < 256; i++) {
        uint32_t crc = i;
        for (int j = 0; j < 8; j++) {
            crc = (crc >> 1) ^ ((crc & 1u) ? poly : 0u);
        }
        crc32_table[0][i] = crc;
    }

    for (int t = 1; t < 8; t++) {
        for (int i = 0; i < 256; i++) {
            crc32_table[t][i] =
                (crc32_table[t - 1][i] >> 8) ^
                crc32_table[0][crc32_table[t - 1][i] & 0xffu];
        }
    }
    crc32_ready = true;
}

