    int ordinal = 0;
    for (int r = 0; r < EPIC_STAR4_HOSTS; r++) {
        if (r == excluded_rank) {
            continue;
        }
        if (r == rank) {
            return ordinal;
        }
        ordinal++;
    }
    return 0;
}

