uint64_t epic_digest(epic_ctx_t *ctx) {
  uint64_t h = 14695981039346656037ull;
  uint32_t window = ctx->retired + ctx->N; if (window > ctx->K) window = ctx->K;
  for (uint32_t p = ctx->retired; p < window; p++) {
    uint32_t i; if (!slot_index(ctx,p,&i)) continue;
    h = fold_bytes(h, &p as u64 LE, 8);
    h = fold_byte(h, mask);
    h = fold_byte(h, complete?1:0);
    switch kind:
      ALLGATHER: for r in 0..3 { h=fold_byte(h,(mask>>r)&1); if present h=fold_bytes(h, base+r*4D, 4D) }
      BCAST: h = fold_bytes(h, base, 4D)
      BARRIER: nothing
      default: for each word: LE bytes
  }
}
