public void add(long start, long end) {
    if (start >= end) return;
    long newStart = start, newEnd = end;
    // find the first interval that could touch/overlap
    Map.Entry<Long,Long> e = intervals.floorEntry(start);
    if (e != null && e.getValue() >= start) {
        newStart = e.getKey();
        newEnd = Math.max(newEnd, e.getValue());
        intervals.remove(e.getKey());
    }
    // merge all following intervals that start <= newEnd
    while (true) {
        Map.Entry<Long,Long> n = intervals.ceilingEntry(newStart);  // strictly greater than newStart? ceilingEntry returns the least key >= newStart
        if (n == null) break;
        if (n.getKey() > newEnd) break;
        newEnd = Math.max(newEnd, n.getValue());
        intervals.remove(n.getKey());
    }
    intervals.put(newStart, newEnd);
}
