                break;
            case 0x04:
                writeVar(out, id);
                writeVar(out, errorCode);
                writeVar(out, finalSize);
                break;
            case 0x05:
                writeVar(out, id);
                writeVar(out, errorCode);
                break;
            case 0x06:
                writeVar(out, offset);
                writeVar(out, length);
