PAD = 1514
BASE = 3029


def range_entry_count(kept):
    return len(kept)


def _coord_sets(interval):
    """Allowed value set of [lo,hi] excluding 1514, as sorted (a,b) tuples."""
    lo, hi = interval
    if lo <= PAD <= hi:
        parts = []
        if lo <= PAD-1:
            parts.append((lo, PAD-1))
        if PAD+1 <= hi:
            parts.append((PAD+1, hi))
        return tuple(parts)
    return ((lo, hi),)


def _canonical(pattern):
    sets = tuple(_coord_sets(iv) for iv in pattern)
    for part in sets:
        if not part:
            return None
    return sets


def _volume(sets):
    v = 1
    for part in sets:
        total = 0
        for a, b in part:
            total += b - a + 1
        v *= total
    return v


def _powers(L):
    """pw[j] = BASE**(L-1-j) (big-endian mixed-radix encoding)."""
    p = [1]
    for _ in range(L-1):
