static void handle_data(collector_t *c, int rank, const rx_info_t *info) {
    uint32_t p = info->p;
    if (p < c->b) {
        c->n_stale++;
        c->repeat[rank] = 1;
        return;
    }
    if (p >= c->b + c->N) {
        c->n_blocked++;
