    }
    uint32_t idx = p % c->N;
    slot_t *s = &c->slots[idx];
    if (s->in_use && s->p != p) {
        c->n_overwrite++;
        free_slot(c, s);
    }
    if (!s->in_use) {
        memset(s, 0, sizeof(*s));
        s->p = p;
        s->in_use = 1;
        c->occupied++;
    }
