    for a in range(K):
        memo = {}
        for b in range(K):
            if b == a:
                continue
            path = []
            cur = b
            while cur != a and cur not in memo:
                cid = pr[a][cur]
                if not _is_int(cid):
                    return False
                if cid < 0 or cid >= 2 * cal.m:
                    return False
                u, v, w, c2 = cal.edges[cid]
                if v != cur:
