```cpp
inline void jword(std::string& o, const Row256& w){
  size_t base = o.size(); o.resize(base+64);
  for (int i=0;i<64;++i) {
     int shift = 4*i;  // bit position of the nibble's LSB, where i counts from the LSB end
     unsigned v=0;
     for(int b=0;b<4;++b) v |= w[shift+b] ? (1u<<b):0u;
     o[base+63-i] = digits[v];
  }
}
