def peel(paths):
    """Return (rounds, core_paths). rounds maps removed canonical edge -> round."""
    current = dict(paths)
    rounds = {}
    rnd = 1
    while True:
        stats = {}
        for p in current:
            first = p[0]
            last = p[-1]
            prev = p[0]
            for cur in p[1:]:
                e = canonical(prev, cur)
                rec = stats.get(e)
                if rec is None:
